// The thin layer that actually talks to lightweight-charts. Everything with
// logic worth testing lives in map/ as pure functions; this file just walks the
// viz object and issues chart calls in a fixed, documented order.
import { AreaSeries, CandlestickSeries, HistogramSeries, LineSeries, createSeriesMarkers, } from "lightweight-charts";
import { arrowMarkers, charMarkers, shapeMarkers } from "./map/markers";
import { barTimes, baseColor, candlePoints, mainCandles, valuePoints } from "./map/series";
import { hlineLineStyle, plotSeriesChoice } from "./map/styles";
const MAIN_PANE = 0;
const SUB_PANE = 1;
function vizOf(source) {
    const viz = "overlay" in source ? source : source.viz;
    if (viz === undefined) {
        throw new Error("no visualization data: pass RunResult.viz (use the object form run(transpileOk, data) — the positional spelling does not carry viz)");
    }
    return viz;
}
export function applyResinViz(chart, source, bars, options = {}) {
    const viz = vizOf(source);
    const barCount = bars.close.length;
    const times = barTimes(bars, barCount);
    const created = [];
    const markerHandles = [];
    const paneOf = (forceOverlay) => (viz.overlay || forceOverlay ? MAIN_PANE : SUB_PANE);
    // 1. Main candles — the anchor everything overlays onto, and the barcolor target.
    let main = null;
    if (options.mainSeries !== false) {
        main = chart.addSeries(CandlestickSeries, {}, MAIN_PANE);
        main.setData(mainCandles(bars, times, viz.barcolors));
        created.push(main);
    }
    // Track a marker/price-line host per pane; fall back across panes when empty.
    const paneHosts = new Map();
    if (main !== null)
        paneHosts.set(MAIN_PANE, main);
    const hostFor = (pane) => paneHosts.get(pane) ?? paneHosts.get(MAIN_PANE) ?? created[0] ?? null;
    // 2. Plots.
    viz.plots.forEach((plot) => {
        const pane = paneOf(plot.forceOverlay);
        const choice = plotSeriesChoice(plot.style);
        const color = baseColor(plot.color, plot.colors, "#2196F3");
        const points = valuePoints(plot.values, times, plot.colors);
        let series;
        if (choice.kind === "histogram") {
            series = chart.addSeries(HistogramSeries, { color, base: plot.histbase }, pane);
        }
        else if (choice.kind === "area") {
            series = chart.addSeries(AreaSeries, { lineColor: color, lineWidth: plot.linewidth }, pane);
        }
        else {
            series = chart.addSeries(LineSeries, {
                color,
                lineWidth: plot.linewidth,
                ...(choice.lineType !== undefined ? { lineType: choice.lineType } : {}),
            }, pane);
        }
        series.setData(points);
        created.push(series);
        if (!paneHosts.has(pane))
            paneHosts.set(pane, series);
    });
    // 3. plotcandle / plotbar as candlestick series (plotbar rendered borderless).
    for (const group of [viz.candles, viz.plotbars]) {
        for (const candle of group) {
            const pane = paneOf(candle.forceOverlay);
            const series = chart.addSeries(CandlestickSeries, {}, pane);
            series.setData(candlePoints(candle, times));
            created.push(series);
            if (!paneHosts.has(pane))
                paneHosts.set(pane, series);
        }
    }
    // 4. Markers — shapes, chars, arrows — attached to the host series of their pane.
    const attachMarkers = (pane, markers) => {
        if (markers.length === 0)
            return;
        const host = hostFor(pane);
        if (host === null)
            return;
        markerHandles.push(createSeriesMarkers(host, markers));
    };
    viz.shapes.forEach((s) => attachMarkers(paneOf(s.forceOverlay), shapeMarkers(s, times)));
    viz.chars.forEach((c) => attachMarkers(paneOf(c.forceOverlay), charMarkers(c, times)));
    viz.arrows.forEach((a) => attachMarkers(paneOf(a.forceOverlay), arrowMarkers(a, times)));
    // 5. hlines as price lines on their pane's host series.
    viz.hlines.forEach((h) => {
        if (h.price === null)
            return; // price only known at runtime — nothing to draw
        const host = hostFor(viz.overlay ? MAIN_PANE : SUB_PANE);
        if (host === null)
            return;
        host.createPriceLine({
            price: h.price,
            color: h.color ?? "#787B86",
            lineStyle: hlineLineStyle(h.linestyle),
            lineWidth: h.linewidth,
            ...(h.title !== null ? { title: h.title } : {}),
        });
    });
    // Not rendered in v1 (see the README support matrix): bgcolors, fills, drawings.
    return {
        series: created,
        remove() {
            for (const m of markerHandles)
                m.setMarkers([]);
            for (const s of created)
                chart.removeSeries(s);
        },
    };
}
